package pe.com.asistencia.schedule.api;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import pe.com.asistencia.employee.repository.EmployeeRepository; import pe.com.asistencia.schedule.domain.*; import pe.com.asistencia.schedule.repository.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/v1/schedules")
public class ScheduleController {
 private final ScheduleRepository schedules; private final ScheduleAssignmentRepository assignments; private final EmployeeRepository employees;
 public ScheduleController(ScheduleRepository s,ScheduleAssignmentRepository a,EmployeeRepository e){schedules=s;assignments=a;employees=e;}
 @GetMapping @PreAuthorize("hasAnyRole('ADMIN','SUPERVISOR')") public List<ScheduleView> list(){return schedules.findAll().stream().map(ScheduleView::of).toList();}
 @PostMapping @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasRole('ADMIN')") public ScheduleView create(@Valid @RequestBody ScheduleRequest r){if(schedules.existsByCodeIgnoreCase(r.code()))throw new ResponseStatusException(HttpStatus.CONFLICT,"El código ya existe");if(r.shifts().stream().map(ShiftRequest::dayOfWeek).distinct().count()!=r.shifts().size())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"No se permite más de un turno por día en esta versión");var s=new Schedule(r.code(),r.name(),r.description());r.shifts().forEach(x->s.addShift(new Shift(x.dayOfWeek(),x.startTime(),x.endTime(),x.breakMinutes())));return ScheduleView.of(schedules.save(s));}
 @PostMapping("/assignments") @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasRole('ADMIN')") public AssignmentView assign(@Valid @RequestBody AssignmentRequest r){if(r.validTo()!=null&&r.validTo().isBefore(r.validFrom()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Rango inválido");if(assignments.overlaps(r.employeeId(),r.validFrom(),r.validTo()))throw new ResponseStatusException(HttpStatus.CONFLICT,"La asignación se superpone con otra vigente");var e=employees.findById(r.employeeId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Empleado no encontrado"));var s=schedules.findById(r.scheduleId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Horario no encontrado"));var a=assignments.save(new ScheduleAssignment(e,s,r.validFrom(),r.validTo()));return AssignmentView.of(a);}
 @GetMapping("/assignments") @PreAuthorize("hasRole('ADMIN')") public List<AssignmentView> assignments(@RequestParam Long employeeId){return assignments.findAllForEmployee(employeeId).stream().map(AssignmentView::of).toList();}
 @PatchMapping("/assignments/{id}/close") @PreAuthorize("hasRole('ADMIN')") public AssignmentView closeAssignment(@PathVariable Long id,@Valid @RequestBody CloseAssignmentRequest r){var assignment=assignments.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Asignación no encontrada"));assignment.close(r.validTo());return AssignmentView.of(assignments.save(assignment));}
 @GetMapping("/me") public ScheduleView mine(Authentication auth){var e=employees.findByUserUsernameIgnoreCase(auth.getName()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Empleado no encontrado"));var list=assignments.findApplicable(e.getId(),LocalDate.now());if(list.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"No hay horario vigente");if(list.size()>1)throw new ResponseStatusException(HttpStatus.CONFLICT,"Existen horarios superpuestos");return ScheduleView.of(list.getFirst().getSchedule());}
 public record ShiftRequest(@Min(1) @Max(7) int dayOfWeek,@NotNull LocalTime startTime,@NotNull LocalTime endTime,@Min(0) int breakMinutes){} public record ScheduleRequest(@NotBlank String code,@NotBlank String name,String description,@NotEmpty List<@Valid ShiftRequest> shifts){} public record ShiftView(Long id,int dayOfWeek,LocalTime startTime,LocalTime endTime,boolean crossesMidnight,int breakMinutes){static ShiftView of(Shift s){return new ShiftView(s.getId(),s.getDayOfWeek(),s.getStartTime(),s.getEndTime(),s.isCrossesMidnight(),s.getBreakMinutes());}} public record ScheduleView(Long id,String code,String name,String description,boolean active,List<ShiftView> shifts){static ScheduleView of(Schedule s){return new ScheduleView(s.getId(),s.getCode(),s.getName(),s.getDescription(),s.isActive(),s.getShifts().stream().map(ShiftView::of).toList());}} public record AssignmentRequest(@NotNull Long employeeId,@NotNull Long scheduleId,@NotNull LocalDate validFrom,LocalDate validTo){} public record CloseAssignmentRequest(@NotNull LocalDate validTo){} public record AssignmentView(Long id,Long employeeId,Long scheduleId,LocalDate validFrom,LocalDate validTo){static AssignmentView of(ScheduleAssignment a){return new AssignmentView(a.getId(),a.getEmployee().getId(),a.getSchedule().getId(),a.getValidFrom(),a.getValidTo());}}
}
